export function buildingCatalogV15Templates() {
  const byId = new Map(PATCHES.map((row) => [row.id, row]));
  return [...DEFAULT_BUILDING_TEMPLATES, HOUSE].map((row) => ({
    ...structuredClone(row), ...structuredClone(byId.get(row.id)), templateVersion: BUILDING_CATALOG_V15_VERSION
  }));
}
